using VisualRelay.App.DesignTime;

namespace VisualRelay.Tests;

/// <summary>
/// Pure view-model assertions (no Avalonia session) that guard the design-time
/// data factory. Every card state must appear in the preview, the running
/// selected card must be mid-progress, and <c>Main.SelectedTask</c> must stay
/// null to avoid triggering <c>SelectTaskAsync</c> disk I/O.
/// </summary>
public sealed class DesignDataTests
{
    [Fact]
    public void Main_CoversEveryCardState()
    {
        var tasks = DesignData.Main.Tasks;

        // Exactly one running row.
        Assert.Single(tasks, t => t.IsRunning);

        // At least one needs-review row that is NOT running.
        Assert.Contains(tasks, t => t.NeedsReview && !t.IsRunning);

        // At least one archived row.
        Assert.Contains(tasks, t => t.IsArchived);

        // At least one row with no run history (CompletedStageCount == 0, not running).
        Assert.Contains(tasks, t => t.Task.CompletedStageCount == 0 && !t.IsRunning);

        // At least one row with a non-empty DayHeader.
        Assert.Contains(tasks, t => !string.IsNullOrEmpty(t.DayHeader));

        // Exactly one selected row.
        Assert.Single(tasks, t => t.IsSelected);
    }

    [Fact]
    public void Main_LeavesSelectedTaskNull_SoPreviewsDoNoDiskIo()
    {
        // MainWindowViewModel.Commands.cs: OnSelectedTaskChanged fires
        // SelectTaskAsync, which reads the markdown file from disk and
        // pollutes StatusText on failure. Keeping SelectedTask null in
        // DesignData avoids all disk I/O at design time.
        Assert.Null(DesignData.Main.SelectedTask);
    }

    [Fact]
    public void Card_IsRunningSelectedMidProgress()
    {
        var card = DesignData.Card;

        Assert.True(card.IsRunning);
        Assert.True(card.IsSelected);
        Assert.InRange(card.ProgressFraction, 0.01, 0.99);
        Assert.Contains("Stage 09 · Fix", card.MetricsLine);
    }
}

